def sets(g):
    ones={tuple(p) for p in np.argwhere(g==1)}
    col={tuple(p) for p in np.argwhere((g!=0)&(g!=1))}
    adj=set()
    for r,c in col:
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            if (r+dr,c+dc) in ones: adj.add((r,c))
    inv1={tuple(p) for p in np.argwhere(g==1)} & {(r+dr,c+dc) for r,c in adj for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]}
    return {'1':ones,'c':col,'a':adj,'i':inv1}
